// Package svelte translates a Svelte component into the TypeScript the
// frontend layer's type checker reads (#221, the owner's decision; ADR
// 007 amended). The translation is svelte2tsx's — Svelte's own, the one
// svelte-check and the Svelte editor extension run — executed in V8
// embedded through cgo, from a bundle generated by scripts/svelte2tsx.sh
// and committed with the versions it pins (VERSIONS). Its output carries
// a source map back to the component, which Output.Original reads.
//
// V8 needs cgo and CGO_CXXFLAGS=-nostdinc++, so it is behind the v8 build
// tag: a build without it converts nothing, Available says so, and the
// layer keeps saying which components it could not read.
package svelte

import (
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	_ "embed"
	"errors"
	"io"
	"strings"
	"sync"
)

// ErrUnavailable is Convert's error in a build without V8.
var ErrUnavailable = errors.New("svelte: this build has no V8 (built without the v8 tag): Svelte components are not translated")

// Shims are the declarations svelte2tsx's output refers to: its helpers
// and markup's elements, by file name.
var Shims = map[string]string{"svelte-shims-v4.d.ts": shimsV4, "svelte-jsx-v4.d.ts": jsxV4}

//go:embed svelte-shims-v4.d.ts
var shimsV4 string

//go:embed svelte-jsx-v4.d.ts
var jsxV4 string

//go:embed svelte2tsx.js.gz
var bundleGz []byte

// Bundle is the svelte2tsx script the converter runs: for the oracle,
// which runs it under Node.
func Bundle() ([]byte, error) {
	r, err := gzip.NewReader(bytes.NewReader(bundleGz))
	if err != nil {
		return nil, err
	}
	return io.ReadAll(r)
}

// An Output is one component's translation.
type Output struct {
	// Code is the TypeScript (TSX) svelte2tsx wrote.
	Code string
	// lines holds, per line of Code, its mapped segments in column order.
	lines [][]segment
}

type segment struct{ col, line, origCol int }

// Original is the component's position, 0-based line and byte column,
// of a 0-based line and column of Code: the mapped segment at or before
// the column on that line. False when nothing on the line maps — the
// code svelte2tsx wrote itself.
func (o *Output) Original(line, col int) (int, int, bool) {
	if line < 0 || line >= len(o.lines) {
		return 0, 0, false
	}
	segs := o.lines[line]
	best := -1
	for i, s := range segs {
		if s.col > col {
			break
		}
		best = i
	}
	if best < 0 {
		return 0, 0, false
	}
	s := segs[best]
	return s.line, s.origCol + (col - s.col), true
}

var (
	cacheMu sync.Mutex
	cache   = map[[32]byte]*Output{}
)

// Convert translates one component, once per content and name: a build
// after an edit translates only the components that changed.
func Convert(src, filename string) (*Output, error) {
	key := sha256.Sum256([]byte(filename + "\x00" + src))
	cacheMu.Lock()
	if o, ok := cache[key]; ok {
		cacheMu.Unlock()
		return o, nil
	}
	cacheMu.Unlock()
	code, mappings, err := convert(src, filename)
	if err != nil {
		return nil, err
	}
	o := &Output{Code: code, lines: decode(mappings)}
	cacheMu.Lock()
	cache[key] = o
	cacheMu.Unlock()
	return o, nil
}

// decode reads a source map's mappings (one source, no names needed):
// segments of base64 VLQ fields, generated column and source, line and
// column, the column relative within a line and the rest across the map.
func decode(mappings string) [][]segment {
	var out [][]segment
	srcLine, srcCol := 0, 0
	for _, l := range strings.Split(mappings, ";") {
		var segs []segment
		col := 0
		for _, field := range strings.Split(l, ",") {
			if field == "" {
				continue
			}
			v := vlq(field)
			if len(v) == 0 {
				continue
			}
			col += v[0]
			if len(v) < 4 {
				continue // a segment that maps nowhere
			}
			srcLine += v[2]
			srcCol += v[3]
			segs = append(segs, segment{col: col, line: srcLine, origCol: srcCol})
		}
		out = append(out, segs)
	}
	return out
}

const b64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

// vlq decodes a field's base64 VLQ values.
func vlq(s string) []int {
	var out []int
	value, shift := 0, 0
	for i := 0; i < len(s); i++ {
		d := strings.IndexByte(b64, s[i])
		if d < 0 {
			return out
		}
		value += (d & 31) << shift
		if d&32 != 0 {
			shift += 5
			continue
		}
		n := value >> 1
		if value&1 != 0 {
			n = -n
		}
		out = append(out, n)
		value, shift = 0, 0
	}
	return out
}
